package com.uop.recordingtools.listener;
import com.uop.recordingtools.UopRecordingToolsPlugin; import org.bukkit.entity.Player; import org.bukkit.event.*; import org.bukkit.event.entity.*; import org.bukkit.event.inventory.*; import org.bukkit.event.player.*; import java.util.*;
public final class RecordingListener implements Listener{private final UopRecordingToolsPlugin plugin;public RecordingListener(UopRecordingToolsPlugin p){plugin=p;p.getServer().getScheduler().runTaskTimer(p,()->p.inventory().tickHistory(),20L,p.getConfig().getLong("history-sample-ticks",10));}@EventHandler public void pre(AsyncPlayerPreLoginEvent e){if(!plugin.protection().allowed(e.getName(),e.getUniqueId(),e.getAddress()))e.disallow(AsyncPlayerPreLoginEvent.Result.KICK_OTHER,"This player identity is protected by UOP Recording Tools.");}@EventHandler public void join(PlayerJoinEvent e){plugin.names().refresh(e.getPlayer());}@EventHandler public void quit(PlayerQuitEvent e){if(plugin.freeze().frozen(e.getPlayer()))plugin.freeze().unfreeze(e.getPlayer());}@EventHandler public void move(PlayerMoveEvent e){Player p=e.getPlayer();if(!plugin.freeze().frozen(p))return;if(e.getTo()!=null&&(e.getFrom().getX()!=e.getTo().getX()||e.getFrom().getY()!=e.getTo().getY()||e.getFrom().getZ()!=e.getTo().getZ())){var to=e.getFrom().clone();to.setYaw(e.getTo().getYaw());to.setPitch(e.getTo().getPitch());e.setTo(to);}}@EventHandler public void damage(EntityDamageEvent e){if(e.getEntity() instanceof Player p&&plugin.freeze().full(p)){e.setCancelled(true);return;}if(e instanceof EntityDamageByEntityEvent x)e.setDamage(e.getDamage()*plugin.damage().multiplier(x.getDamager(),x.getEntity()));}@EventHandler public void drop(PlayerDropItemEvent e){if(plugin.freeze().frozen(e.getPlayer())||plugin.inventory().locked(e.getPlayer()))e.setCancelled(true);}@EventHandler public void pickup(EntityPickupItemEvent e){if(e.getEntity() instanceof Player p&&plugin.freeze().frozen(p))e.setCancelled(true);}@EventHandler public void swap(PlayerSwapHandItemsEvent e){if(plugin.freeze().full(e.getPlayer())||plugin.inventory().locked(e.getPlayer()))e.setCancelled(true);}@EventHandler public void click(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p))return;if(plugin.freeze().full(p)||plugin.inventory().locked(p))e.setCancelled(true);}@EventHandler public void drag(InventoryDragEvent e){if(e.getWhoClicked() instanceof Player p&&(plugin.freeze().full(p)||plugin.inventory().locked(p)))e.setCancelled(true);}@EventHandler public void interact(PlayerInteractEvent e){if(plugin.freeze().full(e.getPlayer()))e.setCancelled(true);}}
